#include <Arduino.h>
#include <TM1637Display.h>

const uint8_t TRIG = 8;
const uint8_t ECHO = 9;
TM1637Display display(4, 5);
unsigned long lastStart = 0;
bool firstSample = true;

void measureAndDisplay() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long width = pulseIn(ECHO, HIGH, 25000UL);
  if (width == 0 || width < 116UL || width > 23200UL) {
    display.clear();
    return;
  }
  int centimeters = (int)((width + 29UL) / 58UL);
  display.showNumberDec(centimeters, false);
}

void setup() {
  pinMode(TRIG, OUTPUT);
  digitalWrite(TRIG, LOW);
  pinMode(ECHO, INPUT);
  display.setBrightness(7);
  display.clear();
}

void loop() {
  unsigned long now = millis();
  if (firstSample || (unsigned long)(now - lastStart) >= 100UL) {
    firstSample = false;
    lastStart = now;
    measureAndDisplay();
  }
}
